// 다시 참가(모집 중 · 나갔던 사람)도 같은 행을 되살린다.
func (q *Queries) UpsertMember(ctx context.Context, arg UpsertMemberParams) error {
	_, err := q.db.Exec(ctx, upsertMember, arg.ChallengeID, arg.UserID, arg.At)
	return err
}

const usePrompt = `-- name: UsePrompt :exec
UPDATE challenge_prompts SET used_at = $1 WHERE id = $2
`

type UsePromptParams struct {
	At pgtype.Timestamptz
	ID string
}

func (q *Queries) UsePrompt(ctx context.Context, arg UsePromptParams) error {
	_, err := q.db.Exec(ctx, usePrompt, arg.At, arg.ID)
	return err
}
